//! Stage 0 baseline corpus for the Android engine migration.
//!
//! The migration plan's stage 0 ends with "frozen current Go behaviour": the bytes and documents the
//! Rust engine has to keep producing while the Go engine is deleted around it. This crate is that
//! freeze. It is **not** in the APK and never becomes a `libditing_*.so`; it is a workspace member so
//! `cargo test` (and therefore `verify.py`) replays it on every run.
//!
//! Four corpora, each generated by the implementation that owns the behaviour and replayed byte for
//! byte:
//!
//! | file | what is frozen | producer |
//! | --- | --- | --- |
//! | `fixtures/dns_answers.json` | synthesized DNS answers (block modes, rewrite, DDR, local asset, SERVFAIL) plus the decoded view of query and answer | [`diting_dns_core::reply`] / [`diting_dns_core::message`] |
//! | `fixtures/contract_documents.json` | the JSON documents Kotlin parses (`getStats`, cache stats/entries, `resolveDomain`, DNS log batch, traffic tick, HTTP event) | [`diting_engine`] and `diting-telemetry-core` |
//! | `fixtures/tun_flows.pcap` | the packet shapes stage 3 must accept: IPv4/IPv6 TCP handshake + data + FIN, UDP DNS, UDP 443 (QUIC), TCP 853 (encrypted DNS) | [`diting_netstack_spike::wire`] |
//! | `fixtures/mitm_exchanges.json` | HTTP/1.1 bodies that get the cosmetic `<link>` spliced in, across gzip/deflate and awkward chunk boundaries | [`diting_mitm_spike::inject`] + [`diting_cosmetic_core`] |
//!
//! Regenerate after a deliberate semantic change:
//!
//! ```bash
//! cargo run -p diting-corpus --bin gen-corpus
//! cargo test -p diting-corpus
//! ```
//!
//! `tests/corpus.rs::fixtures_are_current` regenerates in memory and compares with the committed
//! files, so forgetting the first command turns into a failing test rather than a silent drift.
//!
//! Deliberately **not** in the corpus (they need a device or a peer): DoH/DoT/DoQ wire captures, a
//! real TLS MITM transcript, and anything whose output contains a clock reading (`getDNSCacheEntries` timestamps are frozen as
//! field names only, matching the repo's "时间相关分支靠注入时钟的单测" rule).

use std::path::PathBuf;

pub mod contract;
pub mod dns;
pub mod mitm;
pub mod tun;

/// `rust/diting-corpus/tests/fixtures`.
pub fn fixture_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests")
        .join("fixtures")
}

/// Lower-case hex, the encoding every fixture uses for bytes.
pub fn hex(bytes: &[u8]) -> String {
    const DIGITS: &[u8; 16] = b"0123456789abcdef";
    let mut text = String::with_capacity(bytes.len() * 2);
    for byte in bytes {
        text.push(DIGITS[(byte >> 4) as usize] as char);
        text.push(DIGITS[(byte & 0x0f) as usize] as char);
    }
    text
}

/// The inverse of [`hex`]; `None` for odd lengths or non-hex characters.
pub fn unhex(text: &str) -> Option<Vec<u8>> {
    if !text.len().is_multiple_of(2) {
        return None;
    }
    let bytes = text.as_bytes();
    let mut out = Vec::with_capacity(text.len() / 2);
    for pair in bytes.chunks(2) {
        let high = digit(pair[0])?;
        let low = digit(pair[1])?;
        out.push(high << 4 | low);
    }
    Some(out)
}

fn digit(byte: u8) -> Option<u8> {
    match byte {
        b'0'..=b'9' => Some(byte - b'0'),
        b'a'..=b'f' => Some(byte - b'a' + 10),
        b'A'..=b'F' => Some(byte - b'A' + 10),
        _ => None,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn hex_round_trips() {
        let bytes = [0u8, 1, 15, 16, 127, 128, 255];
        assert_eq!(hex(&bytes), "00010f107f80ff");
        assert_eq!(unhex(&hex(&bytes)), Some(bytes.to_vec()));
        assert_eq!(unhex("abc"), None);
        assert_eq!(unhex("zz"), None);
    }
}
